&lt;li&gt;设置占位背景色：&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% image https://bu.dusays.com/2023/06/01/6478937d7de6f.webp, width=400px, bg=#1D0C04, alt=优化不同宽度浏览的观感 %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;inlineImg-行内图片&#34;&gt;&lt;a href=&#34;#inlineImg-行内图片&#34; class=&#34;headerlink&#34; title=&#34;inlineImg 行内图片&#34;&gt;&lt;/a&gt;inlineImg 行内图片&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;inlineimg&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimg-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimg-2&#34;&gt;参数配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;inlineimg-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimg-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimg-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% inlineImg [src] [height] %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[src] : 图片链接&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;[height] ： 图片高度限制【可选】&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimg-2&#34;&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
&lt;th align=&#34;left&#34;&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;src&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;图片链接&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;height&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;图片高度限制【可选】&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;inlineimg-3&#34;&gt;&lt;p&gt;你看我长得漂亮不&lt;/p&gt;
&lt;p&gt;&lt;img src=&#34;https://bu.dusays.com/2023/06/01/64787ded2ca1c.webp&#34;&gt;&lt;/p&gt;
&lt;p&gt;我觉得很漂亮 &lt;img class=&#34;inline-img&#34; src=&#34;https://bu.dusays.com/2023/06/01/64787da5251b3.png&#34; style=&#34;height:150px&#34;/&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimg-4&#34;&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;你看我长得漂亮不&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;![](https://i.loli.net/2021/03/19/2P6ivUGsdaEXSFI.png)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;我觉得很漂亮 &amp;#123;% inlineImg https://i.loli.net/2021/03/19/5M4jUB3ynq7ePgw.png 150px %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;行内图片-inlineimage&#34;&gt;&lt;a href=&#34;#行内图片-inlineimage&#34; class=&#34;headerlink&#34; title=&#34;行内图片 inlineimage&#34;&gt;&lt;/a&gt;行内图片 inlineimage&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;inlineimage&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimage-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimage-2&#34;&gt;参数配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;inlineimage-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;inlineimage-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimage-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% inlineimage 图片链接, height=高度（可选） %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimage-2&#34;&gt;&lt;ol&gt;
&lt;li&gt;高度：height&amp;#x3D;20px&lt;/li&gt;
&lt;/ol&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;inlineimage-3&#34;&gt;&lt;p&gt;这是 &lt;img no-lazy class=&#34;inline&#34; src=&#34;https://bu.dusays.com/2023/06/01/647895232e5d5.webp&#34; style=&#34;height:1.5em&#34;/&gt; 一段话。&lt;/p&gt;
&lt;p&gt;这又是 &lt;img no-lazy class=&#34;inline&#34; src=&#34;https://bu.dusays.com/2022/05/19/6285328a83ca7.gif&#34; style=&#34;height:40px;&#34;/&gt; 一段话。&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;inlineimage-4&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;这是 &amp;#123;% inlineimage https://bu.dusays.com/2023/06/01/647895232e5d5.webp %&amp;#125; 一段话。&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;这又是 &amp;#123;% inlineimage https://bu.dusays.com/2022/05/19/6285328a83ca7.gif, height=40px %&amp;#125; 一段话。&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;label-标签&#34;&gt;&lt;a href=&#34;#label-标签&#34; class=&#34;headerlink&#34; title=&#34;label 标签&#34;&gt;&lt;/a&gt;label 标签&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;label&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-2&#34;&gt;参数配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;label-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;label-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% label text color %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-2&#34;&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
&lt;th align=&#34;left&#34;&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;text&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;文字&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td align=&#34;left&#34;&gt;color&lt;/td&gt;
&lt;td align=&#34;left&#34;&gt;【可选】背景颜色，默认为 default，default&amp;#x2F;blue&amp;#x2F;pink&amp;#x2F;red&amp;#x2F;purple&amp;#x2F;orange&amp;#x2F;green&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content active&#34; id=&#34;label-3&#34;&gt;&lt;p&gt;臣亮言：&lt;mark class=&#34;hl-label default&#34;&gt;先帝&lt;/mark&gt; 创业未半，而&lt;mark class=&#34;hl-label blue&#34;&gt;中道崩殂&lt;/mark&gt; 。今天下三分，&lt;mark class=&#34;hl-label pink&#34;&gt;益州疲敝&lt;/mark&gt; ，此诚&lt;mark class=&#34;hl-label red&#34;&gt;危急存亡之秋&lt;/mark&gt; 也！然侍衞之臣，不懈于内；&lt;mark class=&#34;hl-label purple&#34;&gt;忠志之士&lt;/mark&gt; ，忘身于外者，盖追先帝之殊遇，欲报之于陛下也。诚宜开张圣听，以光先帝遗德，恢弘志士之气；不宜妄自菲薄，引喻失义，以塞忠谏之路也。&lt;br&gt;宫中、府中，俱为一体；陟罚臧否，不宜异同。若有&lt;mark class=&#34;hl-label orange&#34;&gt;作奸&lt;/mark&gt; 、&lt;mark class=&#34;hl-label green&#34;&gt;犯科&lt;/mark&gt; ，及为忠善者，宜付有司，论其刑赏，以昭陛下平明之治；不宜偏私，使内外异法也。&lt;/p&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;label-4&#34;&gt;&lt;figure class=&#34;highlight plaintext&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;臣亮言：&amp;#123;% label 先帝 %&amp;#125;创业未半，而&amp;#123;% label 中道崩殂 blue %&amp;#125;。今天下三分，&amp;#123;% label 益州疲敝 pink %&amp;#125;，此诚&amp;#123;% label 危急存亡之秋 red %&amp;#125;也！然侍衞之臣，不懈于内；&amp;#123;% label 忠志之士 purple %&amp;#125;，忘身于外者，盖追先帝之殊遇，欲报之于陛下也。诚宜开张圣听，以光先帝遗德，恢弘志士之气；不宜妄自菲薄，引喻失义，以塞忠谏之路也。&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;宫中、府中，俱为一体；陟罚臧否，不宜异同。若有&amp;#123;% label 作奸 orange %&amp;#125;、&amp;#123;% label 犯科 green %&amp;#125;，及为忠善者，宜付有司，论其刑赏，以昭陛下平明之治；不宜偏私，使内外异法也。&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&#34;tab-to-top&#34;&gt;&lt;button type=&#34;button&#34; aria-label=&#34;scroll to top&#34;&gt;&lt;i class=&#34;anzhiyufont anzhiyu-icon-arrow-up&#34;&gt;&lt;/i&gt;&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;

&lt;h2 id=&#34;timeline&#34;&gt;&lt;a href=&#34;#timeline&#34; class=&#34;headerlink&#34; title=&#34;timeline&#34;&gt;&lt;/a&gt;timeline&lt;/h2&gt;&lt;div class=&#34;tabs&#34; id=&#34;timeline&#34;&gt;&lt;ul class=&#34;nav-tabs&#34;&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;timeline-1&#34;&gt;标签语法&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;timeline-2&#34;&gt;参数配置&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab  active&#34; data-href=&#34;timeline-3&#34;&gt;样式预览&lt;/button&gt;&lt;button type=&#34;button&#34; class=&#34;tab &#34; data-href=&#34;timeline-4&#34;&gt;示例源码&lt;/button&gt;&lt;/ul&gt;&lt;div class=&#34;tab-contents&#34;&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;timeline-1&#34;&gt;&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% timeline title,color %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;!-- timeline title --&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;xxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;!-- endtimeline --&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;!-- timeline title --&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;xxxxx&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;lt;!-- endtimeline --&amp;gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% endtimeline %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;/div&gt;&lt;div class=&#34;tab-item-content&#34; id=&#34;timeline-2&#34;&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th align=&#34;left&#34;&gt;参数&lt;/th&gt;
