&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note disabled %&amp;#125;默认 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note default disabled %&amp;#125;default 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note primary disabled %&amp;#125;primary 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note success disabled %&amp;#125;success 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note info disabled %&amp;#125;info 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note warning disabled %&amp;#125;warning 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note danger disabled %&amp;#125;danger 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;ol start=&#34;5&#34;&gt;
&lt;li&gt;&lt;code&gt;no-icon&lt;/code&gt;样式&lt;/li&gt;
&lt;/ol&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note no-icon %&amp;#125;默认 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note default no-icon %&amp;#125;default 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note primary no-icon %&amp;#125;primary 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note success no-icon %&amp;#125;success 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note info no-icon %&amp;#125;info 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note warning no-icon %&amp;#125;warning 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note danger no-icon %&amp;#125;danger 提示块标签&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;方法二&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;图标支持 &lt;code&gt;fontawesome&lt;/code&gt; 和 &lt;code&gt;主题内置的阿里图标&lt;/code&gt;，使用方法为加上对应的类名，&lt;code&gt;fontawesome&lt;/code&gt;图标需开启主题配置文件中&lt;code&gt;icons.fontawesome&lt;/code&gt;，默认未开启 fontawesome&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;p&gt;simple 样式&lt;br&gt;&lt;code&gt;主题内置阿里图标&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note &amp;#x27;anzhiyufont anzhiyu-icon-rocket&amp;#x27; simple %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note blue &amp;#x27;anzhiyufont anzhiyu-icon-bullhorn&amp;#x27; simple %&amp;#125;2022 年快到了....&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note pink &amp;#x27;anzhiyufont anzhiyu-icon-instagram&amp;#x27; simple %&amp;#125;小心开车 安全至上&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note red &amp;#x27;anzhiyufont anzhiyu-icon-fan&amp;#x27; simple%&amp;#125;这是三片呢？还是四片？&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note orange &amp;#x27;anzhiyufont anzhiyu-icon-dengpao&amp;#x27; simple %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note purple &amp;#x27;anzhiyufont anzhiyu-icon-sanmingzhi&amp;#x27; simple %&amp;#125;剪刀石头布&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note green &amp;#x27;anzhiyufont anzhiyu-icon-ic&lt;span class=&#34;emphasis&#34;&gt;_train&amp;#x27; simple %&amp;#125;前端最讨厌的浏览器&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;fontawesome 图标&lt;/code&gt;，开启主题配置文件中的&lt;code&gt;icons.fontawesome&lt;/code&gt;为&lt;code&gt;true&lt;/code&gt;后可见&lt;/p&gt;

&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note &amp;#x27;fab fa-cc-visa&amp;#x27; simple %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note blue &amp;#x27;fas fa-bullhorn&amp;#x27; simple %&amp;#125;2022 年快到了....&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note pink &amp;#x27;fas fa-car-crash&amp;#x27; simple %&amp;#125;小心开车 安全至上&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note red &amp;#x27;icon-fan&amp;#x27; simple%&amp;#125;这是三片呢？还是四片？&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note orange &amp;#x27;fas fa-battery-half&amp;#x27; simple %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note purple &amp;#x27;far fa-hand-scissors&amp;#x27; simple %&amp;#125;剪刀石头布&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note green &amp;#x27;fab fa-internet-explorer&amp;#x27; simple %&amp;#125;前端最讨厌的浏览器&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;modern 样式&lt;br&gt;&lt;code&gt;主题内置阿里图标&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note &amp;#x27;anzhiyufont anzhiyu-icon-rocket&amp;#x27; modern %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note blue &amp;#x27;anzhiyufont anzhiyu-icon-bullhorn&amp;#x27; modern %&amp;#125;2022 年快到了....&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note pink &amp;#x27;anzhiyufont anzhiyu-icon-instagram&amp;#x27; modern %&amp;#125;小心开车 安全至上&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note red &amp;#x27;anzhiyufont anzhiyu-icon-fan&amp;#x27; modern%&amp;#125;这是三片呢？还是四片？&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note orange &amp;#x27;anzhiyufont anzhiyu-icon-dengpao&amp;#x27; modern %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note purple &amp;#x27;anzhiyufont anzhiyu-icon-sanmingzhi&amp;#x27; modern %&amp;#125;剪刀石头布&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note green &amp;#x27;anzhiyufont anzhiyu-icon-ic&lt;span class=&#34;emphasis&#34;&gt;_train&amp;#x27; modern %&amp;#125;前端最讨厌的浏览器&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;code&gt;fontawesome 图标&lt;/code&gt;，开启主题配置文件中的&lt;code&gt;icons.fontawesome&lt;/code&gt;为&lt;code&gt;true&lt;/code&gt;后可见&lt;/p&gt;

&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note &amp;#x27;fab fa-cc-visa&amp;#x27; modern %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note blue &amp;#x27;fas fa-bullhorn&amp;#x27; modern %&amp;#125;2021 年快到了....&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note pink &amp;#x27;fas fa-car-crash&amp;#x27; modern %&amp;#125;小心开车 安全至上&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note red &amp;#x27;icon-fan&amp;#x27; modern%&amp;#125;这是三片呢？还是四片？&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note orange &amp;#x27;fas fa-battery-half&amp;#x27; modern %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note purple &amp;#x27;far fa-hand-scissors&amp;#x27; modern %&amp;#125;剪刀石头布&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note green &amp;#x27;fab fa-internet-explorer&amp;#x27; modern %&amp;#125;前端最讨厌的浏览器&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;flat 样式&lt;br&gt;&lt;code&gt;主题内置阿里图标&lt;/code&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight markdown&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note &amp;#x27;anzhiyufont anzhiyu-icon-rocket&amp;#x27; flat %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note blue &amp;#x27;anzhiyufont anzhiyu-icon-bullhorn&amp;#x27; flat %&amp;#125;2022 年快到了....&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note pink &amp;#x27;anzhiyufont anzhiyu-icon-instagram&amp;#x27; flat %&amp;#125;小心开车 安全至上&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note red &amp;#x27;anzhiyufont anzhiyu-icon-fan&amp;#x27; flat%&amp;#125;这是三片呢？还是四片？&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note orange &amp;#x27;anzhiyufont anzhiyu-icon-dengpao&amp;#x27; flat %&amp;#125;你是刷 Visa 还是 UnionPay&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note purple &amp;#x27;anzhiyufont anzhiyu-icon-sanmingzhi&amp;#x27; flat %&amp;#125;剪刀石头布&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;% note green &amp;#x27;anzhiyufont anzhiyu-icon-ic&lt;span class=&#34;emphasis&#34;&gt;_train&amp;#x27; flat %&amp;#125;前端最讨厌的浏览器&amp;#123;% endnote %&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt